head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00401";
scwin.obj = undefined;
scwin.chkArrNo = undefined;
scwin.chkTitle = undefined;
scwin.fn_selectComplate = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_docPage.get("total")) + "건 (" + String(dma_docPage.get("currentPage")) + "/" + String(dma_docPage.get("endListPage")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_deleteReq').set('pageIndex', "1");
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const rtnVal = "";
        $("#ipt_checkAll").click(function() {
                if ($(this).is(":checked")) {
                    $("input:checkbox[name='selDiscls']").attr("checked", true);
                } else {
                    $("input:checkbox[name='selDiscls']").attr("checked", false);
                }
                scwin.setAllValue();
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00401.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.chkArrNo =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00401' }); }

try { scwin.chkTitle =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00401' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.fn_selectComplate = scwin.tx_fn_selectComplate;
        scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00401.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_searchBeginDd_onblur
 * @description cal_searchBeginDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchBeginDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchBeginDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00401.cal_searchBeginDd_onblur' }); }
};

/**
 * @method
 * @name cal_searchEndDd_onblur
 * @description cal_searchEndDd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_searchEndDd_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_searchEndDd"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00401.cal_searchEndDd_onblur' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00401.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00401.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: checkIt (인자 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_selectComplate_onclick
 * @description btn_selectComplate 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_selectComplate_onclick = function(e){
    try {
        scwin.fn_selectComplate()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00401.btn_selectComplate_onclick' }); }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function(e){
    try {
        await scwin.close()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00401.btn_close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "",
        ref: "dma_deleteReq",
        target: "dlt_docPageList=body",
        isProcessMsg: false
    };
    return await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/submission/searchDisclosureDocument.do?method=removeWritingDocument",
        ref: "dma_deleteReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_selectComplate
 * @description select Complate 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_selectComplate = async function () {
    const sbmOptions = {
        id: "tx_fn_selectComplate",
        method: "post",
        action: "/submission/searchDisclosureDocument.do",
        ref: "dma_selectComplateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/submission/searchDisclosureDocument.do",
        ref: "dma_loadListReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_127").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_docPageList_fmt_column7
 * @description grd doc Page List fmt column7 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초문서"; }
        if (v === 'M') { return "본문정정"; }
        if (v === 'U') { return "첨부정정"; }
        if (v === 'A') { return "첨부추가"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column7" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column8
 * @description grd doc Page List fmt column8 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column8 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "langTpCd") ?? '') : '');
        if (v === '0') { return "국문"; }
        if (v === '1') { return "영문"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column8" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_submitNm
 * @description grd doc Page List fmt submit Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_submitNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "wrtrptMaindocTpCd") ?? '') : '');
        if (v === '1') { return String((dl && dl.getCellData ? dl.getCellData(r, "submitNm") : '') ?? ''); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.submitNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name setAllValue
 * @description set All Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.setAllValue = function () {
    const chkObj = document.getElementsByName('selDiscls');
    for (let i = 0; i < chkObj.length; i++) {
        scwin.checkIt(chkObj[i]);
    }
};

/**
 * @method
 * @name checkDocSubmitTp
 * @description check Doc Submit Tp 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDocSubmitTp = async function () {
    const docSubmitTp = 'null';
    if (docSubmitTp === '1') {
        await $c.win.alert('이미 제출 완료된 보고서 입니다.');
    } else {
        if (docSubmitTp === '2') {
            await $c.win.alert('이미 제출 삭제된 보고서 입니다.');
        } else {
            if (docSubmitTp === '0') {
                await $c.win.alert('정상 삭제되었습니다.');
            }
        }
    }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_searchBeginDd').getValue()> $c.util.getComponent('cal_searchEndDd').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name deleteDeleteReq
 * @description delete Delete Req 처리
 * @param {*} applNo applNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteDeleteReq = async function (applNo) {
    if (await $c.win.confirm('삭제하시겠습니까?')) {
        (document.searchForm || { elements: [] }).action = "/submission/searchDisclosureDocument.do?method=removeWritingDocument";
        $c.util.getComponent('dma_deleteReq').set('applNo', applNo);
        await scwin.tx_fn_delete();
    }
};

/**
 * @method
 * @name checkIt
 * @description check It 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.checkIt = function (ver) {
    scwin.obj = (document.deleteform || { elements: [] });
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if (scwin.chkArrNo.length !== 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkTitle.join(",");
    (($c.util.getComponent("txt_docs")) && ($c.util.getComponent("txt_docs")).setValue ? ($c.util.getComponent("txt_docs")).setValue(scwin.chkTitle.join("<br/>")) : (($c.util.getComponent("txt_docs")) ? (($c.util.getComponent("txt_docs")).innerHTML = scwin.chkTitle.join("<br/>")) : void (scwin.chkTitle.join("<br/>"))));
};

/**
 * @method
 * @name resetRtnVal
 * @description reset Rtn Val 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.resetRtnVal = function (ver) {
    const tmpArr1 = [];
    const tmpArr2 = [];
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = [];
    scwin.chkTitle = [];
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.close = async function () {
    if (await $c.win.confirm('공시 삭제를 종료하시겠습니까?')) {
        $c.win.closePopup();
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name krxpage_pagenavigator_127_onclick
 * @description krxpage_pagenavigator_127 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_127_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_127.page' }); } await scwin.tx_load_list(); };
